/*selectSellerMpIvObtnodrReceiptDetailPopList_v2*/ SELECT (SELECT DECODE(COUNT(COD.CODE),0,'N','Y') FROM ICOMCOD1 COD WHERE 1=1 AND COD.CODE = E.CMS_CATEG_ID AND COD.TYPE = 'CM11' AND COD.FLAG = 'Y') AS COD_CHECK, ---ICOMCOD1 CHECK DECODE(TRIM(E.MSDS_NO),'','Y','MS88888888','Y','N') AS MSDS_CHECK, --BYIT.MSDS_NO CHECK (SELECT DECODE(COUNT(REQ.BUYER_ITEM_NO),0,'N','Y') FROM KEP_CMC_REQ REQ WHERE 1=1 AND REQ.BUYER = A.BUYER AND REQ.BYIT_COMORG_CODE = E.BUYER AND REQ.BUYER_ITEM_NO = E.BUYER_ITEM_NO AND REQ.AGENT = C.AGENT AND REQ.REQ_STATUS NOT IN ('B','C','D','N','T')) AS REQ_CHECK, ---REQ CHECK (SELECT DECODE(COUNT(REQ.BUYER_ITEM_NO),0,'N','Y') FROM KEP_CMC_REQ REQ WHERE 1=1 AND REQ.BUYER = A.BUYER AND REQ.BYIT_COMORG_CODE = E.BUYER AND REQ.BUYER_ITEM_NO = E.BUYER_ITEM_NO AND REQ.AGENT = C.AGENT AND REQ.REQ_STATUS IN ('P','S') AND REQ.TEMP_COND IS NOT NULL AND REQ.REQ_NO = (SELECT MAX(REQ_NO) FROM KEP_CMC_REQ WHERE 1=1 AND BUYER = A.BUYER AND BYIT_COMORG_CODE = E.BUYER AND BUYER_ITEM_NO = E.BUYER_ITEM_NO AND AGENT = C.AGENT) ) AS TEMP_REQ_CHECK, ---TEMP_REQ_CHECK DECODE(E.MATERIAL_TYPE, 'H', 'Y', 'N') AS HARMFUL_CHECK, DECODE(TRIM(E.TEMP_COND), '', 'Y', NULL, 'Y', 'N') AS TEMP_CHECK, (SELECT DECODE(COUNT(COD.CODE),0,'N','Y') FROM ICOMCOD1 COD WHERE 1=1 AND COD.CODE = E.CMS_CATEG_ID AND COD.TYPE = 'CM11' AND COD.TEXT1 = 'Y' AND COD.FLAG = 'Y') AS SG118_CHECK, E.TEMP_COND, '/ ' || (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M203' AND CODE = E.TEMP_COND AND FLAG = 'Y') AS TEMP_COND_TEXT, '/ ' || E.TEMP_RANGE AS TEMP_RANGE, DECODE(E.MATERIAL_TYPE, 'H', '/ 유해화학물질','') AS HARMFUL_TEXT, A.REF_PR_NO AS REF_PR_NO, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, A.DESCRIPTION||DECODE(TRIM(A.MAKER_NAME),NULL,'',' / '||A.MAKER_NAME) AS DESCRIPTION, A.SPECIFICATION AS SPECIFICATION, A.ITEM_QTY AS ITEM_QTY, A.UNIT_MEASURE AS UNIT_MEASURE, DECODE(A.PROXY_BUY_FLAG, 'PX', A.AGENT_PRICE, A.UNIT_PRICE) AS UNIT_PRICE, DECODE(A.PROXY_BUY_FLAG, 'PX', A.AGENT_ITEM_AMT, A.ITEM_AMT) AS ITEM_AMT, -- DECODE(A.PROCESS_TYPE, '0',A.RD_DATE, F_GET_DATE_TR(A.RD_DATE)) AS RD_DATE, A.RD_DATE AS RD_DATE, -- DECODE(A.PROCESS_TYPE, '0',A.ST_DATE, F_GET_DATE_TR(A.ST_DATE)) AS ST_DATE, A.ST_DATE AS ST_DATE, A.BUYER AS BUYER, A.PO_NO AS PO_NO, A.PO_SEQ AS PO_SEQ, (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BYCA_COMORG_CODE, A.DS_FLAG AS DS_FLAG, A.DS_DELAY_REASON AS DS_DELAY_REASON, DECODE(A.DS_FLAG,'N','btn_basic01.gif','R','btn_basic01.gif','Y','btn_complete01.gif') AS DS_FLAG_IMG, DECODE(NVL(A.DS_DELAY_REASON,'icon') , 'icon' ,'btn_basic02.gif','btn_complete02.gif') AS DS_DELAY_REASON_IMG, 'btn_basic03.gif' AS DS_REJECT_REASON_IMG, A.SELLER AS SELLER, A.DS_DATE AS DS_DATE, D.DS_FLAG AS CMPY_DS_FLAG, A.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, A.CONTRACT_NO AS CONTRACT_NO, A.CONTRACT_SEQ AS CONTRACT_SEQ, C.DS_FLAG AS H_DS_FLAG, A.PO_REMARK ||DECODE(TRIM(A.LEGACY_PO_NO),NULL,' ', ' ('||A.LEGACY_PO_NO||' , '||A.LEGACY_PO_SEQ||') ')||DECODE(TRIM(A.REF_IF_NO),NULL,NULL,'('||A.REF_IF_NO||')') AS PO_REMARK, C.DOC_TYPE AS DOC_TYPE, DECODE(C.DOC_TYPE,'X',SUBSTR(A.BUYER_ITEM_NO,1,7), (SELECT STDCATLG_ID FROM ICOMCQDT WHERE BUYER = A.BYIT_COMORG_CODE AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ)) AS STDCATLG_ID, DECODE(C.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(A.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, B.IMAGE_KEY AS IMAGE_KEY, DECODE(B.IMAGE_KEY,NULL,'','Y') AS IMAGE_KEY_YN, (SELECT BYIT.REFINE_NOTE FROM ICOMBYIT BYIT, ICOMCMPY CMPY WHERE BYIT.BUYER = CMPY.BYCA_COMORG_CODE AND CMPY.COM_CODE = A.BUYER AND BYIT.BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS REFINE_NOTE, (SELECT DECODE(MAX(WM.WMRE_NO),'','N','Y') FROM BNTWMRE WM WHERE WM.BUYER = A.BUYER AND WM.PO_NO = A.PO_NO AND WM.PO_SEQ = A.PO_SEQ ) WMRE_NO_YN, (SELECT DECODE(MAX(WM.WMRE_NO),'','N','Y') FROM BNTWMRE WM WHERE WM.BUYER = A.BUYER AND WM.PO_NO = A.PO_NO AND WM.PO_SEQ = A.PO_SEQ AND WM.CANCEL_DATE IS NULL AND WM.END_DATE IS NULL ) WMRE_CANCEL_NO_YN, (SELECT DECODE(COUNT(COD.CODE2),0,'N','Y') FROM ICOMCOD3 COD WHERE 1=1 AND COD.BUYER = A.BUYER AND COD.TYPE = 'BICT' AND COD.CODE2 = A.CATEG_ID AND COD.FLAG = 'Y' ) AS SIZE_YN, B.SIZE_QTY, B.SIZE_LEN, E.KEP_MAKER_PART_NO, E.MAKER_PART_NO, F_GET_BUY_CLOSE_DATE_CHK(A.BUYER, A.PO_NO, A.PO_SEQ, C.AGENT) AS BUY_CLOSE_DATE_CHK, A.ITEM_MAKE_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = A.ITEM_MAKE_TYPE) AS ITEM_MAKE_TYPE_TEXT, C.PO_CREATE_DATE AS PH_PO_DATE, A.PROCESS_TYPE AS PROCESS_TYPE, A.WAREHOUSE_CODE AS WAREHOUSE_CODE, DECODE(A.PROCESS_TYPE, '2', DECODE((SELECT COUNT(*) FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'B' AND FLAG = 'Y' AND TEXT1 = A.WAREHOUSE_CODE), 0, 'N', 'Y'),'N') AS TR_WAREHOUSE_YN, 'N' AS BUYER_NEED_DELI, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(A.BUYER, '01')) AS BUYER_NAME FROM ICOMPRDT B, ICOMPODT A , ICOMPOHD C, ICOMCMPY D, ICOMBYIT E WHERE A.BUYER = #{st_buyer}
AND A.PO_NO IN
#{item}
AND A.BUYER = B.BUYER AND A.PR_NO = B.PR_NO AND A.PR_SEQ = B.PR_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND A.BUYER = D.COM_CODE AND B.BYIT_COMORG_CODE = E.BUYER (+) AND B.BUYER_ITEM_NO = E.BUYER_ITEM_NO (+) AND A.DS_FLAG <> 'Y' AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D'


		 	SELECT /*getSellerMpivObtnodrReceiptOrderCheck*/
