/* insertSellerMpivObtnodrReceiptOrder */ INSERT INTO ICOMPORS ( BUYER , PO_NO , PO_SEQ , DS_SEQ , STATUS , SEND_DATE , SEND_TIME , ADD_DATE , ADD_TIME , CHANGE_DATE , CHANGE_TIME , CONFIRM_DATE , CONFIRM_TIME , SELLER , BUYER_ITEM_NO , SELLER_ITEM_NO , DESCRIPTION , SPECIFICATION , UNIT_MEASURE , CD_DATE , CD_QTY , DS_DATE , ADD_USER_ID , ADMIN_FLAG1 , BUYER_DS_DATE , AGENT
, AGENCY_USER_ID
) ( SELECT BUYER , PO_NO , PO_SEQ , (SELECT TO_CHAR(NVL(MAX(DS_SEQ)+1, 1), 'FM000000') FROM ICOMPORS WHERE BUYER = #{st_buyer} AND PO_NO = #{st_po_no} AND PO_SEQ = #{st_po_seq}) , 'C' , ' ' , ' ' , TO_CHAR(SYSDATE, 'YYYYMMDD') , TO_CHAR(SYSDATE, 'HH24MISS') , TO_CHAR(SYSDATE, 'YYYYMMDD') , TO_CHAR(SYSDATE, 'HH24MISS') , ' ' , ' ' , SELLER , BUYER_ITEM_NO , SELLER_ITEM_NO , DESCRIPTION , SPECIFICATION , UNIT_MEASURE , #{st_ds_date} , #{st_cd_qty} , #{st_ds_date} , #{st_user_id} , #{admin_flag1} AS ADMIN_FLAG1 , DECODE(PROCESS_TYPE,'0',#{st_ds_date},'2',KEP.F_GET_WMS_DS(BUYER,WAREHOUSE_CODE,#{st_ds_date})) ,#{st_com_code}
, #{st_kep_id}
FROM ICOMPODT WHERE SELLER = #{st_seller} AND PO_NO = #{st_po_no} AND PO_SEQ = #{st_po_seq} AND BUYER = #{st_buyer} AND STATUS != 'D' )


/* updateSellerMpivObtnodrProductInfo */
	UPDATE ICOMPODT
	SET 
		  DS_DATE			= #{st_max_cd_date}
		, DS_FLAG			= #{st_ds_flag}
		, DO_QTY			= #{st_po_qty}
		, DS_DELAY_REASON	= #{st_delay_reason}
		, DS_YN				= DECODE( (SELECT DS_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_buyer}), 'Y', 'Y', DECODE( (SELECT DS_FLAG FROM ICOMPOHD WHERE BUYER = #{st_buyer} AND PO_NO = #{st_po_no}), 'Y', 'Y', #{st_ds_yn}) )
	WHERE
			BUYER	= #{st_buyer}
		AND SELLER	= #{st_seller}
		AND PO_NO	= #{st_po_no}
		AND PO_SEQ	= #{st_po_seq}


/* updateSellerMpivObtnodrMasterInfo */
	UPDATE ICOMPOHD
	SET   DS_FLAG = DECODE((SELECT COUNT(*) FROM ICOMPODT WHERE BUYER = #{st_buyer} AND PO_NO = #{st_po_no} AND STATUS <> 'D' AND DS_YN = 'Y'), 0, 'N', 'Y')
		, CONFIRM_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
		, CONFIRM_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
		, CONFIRM_USER_ID = #{st_user_id}
	WHERE
		BUYER = #{st_buyer}
		AND PO_NO = #{st_po_no}

/* insertSellerMpIvChemicalInfo */ INSERT INTO KEP_CMC_REQ ( REQ_NO, BYIT_COMORG_CODE, BUYER, BUYER_ITEM_NO, REQ_STATUS, REQ_DATE, REQ_USER_ID, AGENT, ADD_DATE, ADD_USER_ID, CHANGE_DATE, CHANGE_USER_ID ) SELECT F_GET_NO('KRKORE0001','CM') AS REQ_NO, X.BYIT_COMORG_CODE, X.BUYER, X.BUYER_ITEM_NO, X.REQ_STATUS, X.REQ_DATE, X.REQ_USER_ID, X.AGENT, X.ADD_DATE, X.ADD_USER_ID, X.CHANGE_DATE, X.CHANGE_USER_ID FROM ( SELECT (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{st_buyer}) AS BYIT_COMORG_CODE, #{st_buyer} AS BUYER, C.BUYER_ITEM_NO AS BUYER_ITEM_NO, 'Q' AS REQ_STATUS, SYSDATE AS REQ_DATE, #{st_user_id} AS REQ_USER_ID, A.AGENT AS AGENT, SYSDATE AS ADD_DATE, #{st_user_id} AS ADD_USER_ID, SYSDATE AS CHANGE_DATE, #{st_user_id} AS CHANGE_USER_ID FROM ICOMPOHD A, ICOMBYIT B ,ICOMPODT C WHERE 1=1 AND A.BUYER = #{st_buyer} AND A.PO_NO = #{st_po_no} AND A.PO_NO = C.PO_NO AND A.BUYER = C.BUYER AND C.BYIT_COMORG_CODE = B.BUYER AND C.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND TRIM(B.MSDS_NO) IS NULL AND B.CMS_CATEG_ID IN ( SELECT CODE FROM ICOMCOD1 COD1 WHERE COD1.TYPE = 'CM11' AND COD1.FLAG = 'Y' ) AND A.STATUS != 'D' AND C.STATUS != 'D' AND NOT EXISTS (SELECT 'X' FROM KEP_CMC_REQ WHERE BYIT_COMORG_CODE = B.BUYER AND BUYER_ITEM_NO = B.BUYER_ITEM_NO AND AGENT = A.AGENT AND REQ_STATUS = 'Q')
UNION
SELECT (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{st_buyer}) AS BYIT_COMORG_CODE, #{st_buyer} AS BUYER, C.BUYER_ITEM_NO AS BUYER_ITEM_NO, 'Q' AS REQ_STATUS, SYSDATE AS REQ_DATE, #{st_user_id} AS REQ_USER_ID, A.AGENT AS AGENT, SYSDATE AS ADD_DATE, #{st_user_id} AS ADD_USER_ID, SYSDATE AS CHANGE_DATE, #{st_user_id} AS CHANGE_USER_ID FROM ICOMPOHD A, ICOMBYIT B ,ICOMPODT C WHERE 1=1 AND A.BUYER = #{st_buyer} AND A.PO_NO = #{st_po_no} AND A.PO_NO = C.PO_NO AND A.BUYER = C.BUYER AND C.BYIT_COMORG_CODE = B.BUYER AND C.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER IN ( SELECT B.COM_CODE FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND A.SLG_ID = 'P07-0000033' ) AND (TRIM(B.TEMP_COND) IS NULL OR TRIM(B.TEMP_RANGE) IS NULL) AND B.CMS_CATEG_ID IN ( SELECT CODE FROM ICOMCOD1 COD1 WHERE COD1.TYPE = 'CM11' AND COD1.TEXT1 = 'Y' AND COD1.FLAG = 'Y' ) AND A.STATUS != 'D' AND C.STATUS != 'D' AND NOT EXISTS (SELECT 'X' FROM KEP_CMC_REQ WHERE BYIT_COMORG_CODE = B.BUYER AND BUYER_ITEM_NO = B.BUYER_ITEM_NO AND AGENT = A.AGENT AND REQ_STATUS = 'Q') ) X

mapper.select:

/* selectSellerMpivObtnodrDelayChk */
	SELECT	TO_DATE(#{st_ds_date}, 'YYYYMMDD') - TO_DATE(ST_DATE, 'YYYYMMDD') AS DELAY_DIFF_DAYS
	FROM	ICOMPODT
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PO_NO = #{st_po_no}
	AND		PO_SEQ = #{st_po_seq}


/* selectSellerMpivObtnodrRdDateChk */
	SELECT	TO_DATE(#{st_ds_date}, 'YYYYMMDD') - TO_DATE(RD_DATE, 'YYYYMMDD') AS DELAY_DIFF_DAYS
	FROM	ICOMPODT
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PO_NO = #{st_po_no}
	AND		PO_SEQ = #{st_po_seq}


/* selectSellerMpivObtnodrLongDelayChk */
	SELECT	TO_DATE(#{st_ds_date}, 'YYYYMMDD') - TO_DATE(ADD_DATE, 'YYYYMMDD') AS LONG_DELAY_DIFF_DAYS
	FROM	ICOMPODT
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PO_NO = #{st_po_no}
	AND		PO_SEQ = #{st_po_seq}


/* selectSellerMpivObtnodrIssueRegExceptChk */
	SELECT	DECODE(COUNT(*), 0, 'N', 'Y') AS EXCEPT_YN
	FROM	ICOMCOD3
	WHERE	1=1
	AND		TYPE = 'ISSUE_EX'
	AND		BUYER = #{st_buyer}
	AND		CODE1 IN ('ALL', #{st_com_code})
	AND		CODE2 = #{PMNGTYPE}
	AND		FLAG = 'Y'
